from datetime import datetime, timedelta

def parse_excel_date(val):
    """
    Converts Excel serial dates (integers/floats) to YYYY-MM-DD.
    Excel base date is usually 1899-12-30.
    """
    try:
        # Try to parse as a number first
        num = float(val)
        # Excel dates are positive numbers. 
        # 1 is 1899-12-31 (or 1900-01-01 depending on leap year bug handling)
        # Standard library approach for most modern Excel files:
        base_date = datetime(1899, 12, 30)
        dt = base_date + timedelta(days=num)
        return dt.strftime("%Y-%m-%d")
    except (ValueError, TypeError):
        return None

def parse_date(date_str):
    """Parses YYYYMMDD or YYYY-MM-DD into a YYYY-MM-DD string."""
    if not date_str or str(date_str).strip() == "":
        return None
    date_str = str(date_str).strip()

    # First, check if it's an Excel serial date (all digits, likely 5 digits)
    if date_str.isdigit() and len(date_str) <= 6:
        return parse_excel_date(date_str)

    # Try common string formats
    for fmt in ("%Y%m%d", "%Y-%m-%d"):
        try:
            return datetime.strptime(date_str, fmt).strftime("%Y-%m-%d")
        except ValueError:
            continue

    # If it's a number but not caught by isdigit (e.g. float string)
    excel_dt = parse_excel_date(date_str)
    if excel_dt:
        return excel_dt

    return None

def format_wage(val):
    """Formats wage as a decimal string."""
    try:
        f_val = float(val)
        # Use format to avoid scientific notation. 
